C = "Operations & HR"
SPECS = [
 dict(type="I", slug="employee-onboarding-kickoff", category=C, name="Employee onboarding kickoff (welcome email, checklist log, manager alert)",
  summary="When HR submits a new-hire form, the hire gets a welcome email, the manager is told, and the checklist is logged in a sheet.",
  fields=["name","email","role","start_date","manager_email"], tab="New hires", trigger="form", form_title="New hire details", cfg=dict(handbook_link="https://example.com/handbook"),
  reply=dict(subject="Welcome to {cfg.business_name}, {name}", body="Hi {name},\n\nWelcome aboard as {role}! Your first day is {start_date}. Handbook: {cfg.handbook_link}\n\nSee you soon,\n{cfg.sender_name}"),
  notify=dict(via="gmail", subject="New hire starting: {name}", text="{name} joins as {role} on {start_date}. Manager: {manager_email}. Please prepare accounts and equipment.")),
 dict(type="I", slug="leave-request-approval-slack", category=C, name="Leave request log with Slack approval ping",
  summary="Staff request time off through a form. It is logged and posted to Slack for the manager.",
  fields=["name","email","from_date","to_date","reason"], tab="Leave requests", trigger="form", form_title="Request time off",
  reply=dict(subject="We received your leave request", body="Hi {name},\n\nYour request for {from_date} to {to_date} was received. You will hear back soon.\n\n{cfg.sender_name}"),
  notify=dict(via="slack", text="Leave request from {name}: {from_date} to {to_date}. Reason: {reason}")),
 dict(type="I", slug="meeting-notes-action-items-ai", category=C, name="Meeting notes to summary and action items (AI)",
  summary="Send a transcript or notes to a webhook. AI writes a summary, decisions and action items with owners, saved and emailed.",
  fields=["meeting_title","attendees","notes"], tab="Meetings", trigger="form", form_title="Meeting notes",
  ai=dict(label="summarise the meeting", prompt="Summarise this meeting. Give a three-sentence summary, the decisions made, and action items with an owner and due date if mentioned. Do not invent owners.",
          schema={"summary":"Three sentences","decisions":"- ...","action_items":"- Owner: task (due)"}),
  notify=dict(via="gmail", subject="Meeting summary: {meeting_title}", text="{summary}\n\nDecisions:\n{decisions}\n\nAction items:\n{action_items}")),
 dict(type="D", slug="weekly-kpi-report-email", category=C, name="Weekly KPI report email from a metrics sheet",
  summary="Each Monday reads your KPI sheet and emails a short report: what moved, by how much, and what to look at.",
  tab="KPIs", cols=["week","metric","value","target"], when="weekly 1 8",
  prompt="You are an operations analyst. From these KPI rows compare each metric's latest value to its target and previous week. Say what improved, what slipped, and the one thing to look at first."),
 dict(type="I", slug="daily-standup-collector", category=C, name="Daily standup collector (form answers into one digest)",
  summary="Team members fill a 3-question form. Answers are logged in a sheet and posted to Slack as they come in.",
  fields=["name","yesterday","today","blockers"], tab="Standups", trigger="form", form_title="Daily standup",
  notify=dict(via="slack", text="Standup from {name}\nYesterday: {yesterday}\nToday: {today}\nBlockers: {blockers}")),
 dict(type="G", slug="job-application-screener-ai", category=C, name="Job application screener (AI summary against your criteria)",
  summary="Reads application emails, scores the match against your criteria, and logs a short summary. A helper for a human to decide, never an auto-reject.",
  tab="Applicants", query="in:inbox -from:me (application OR resume OR CV)", cfg=dict(criteria="3+ years bookkeeping, QuickBooks, good written English"),
  prompt="You help a small business read job applications. Criteria: {cfg.criteria}. Say if this is an application, give a match score 1-10 against the criteria with a one-sentence reason, and list anything missing. Do not judge on age, gender, nationality or other protected traits.",
  schema={"is_application":True,"match_score":7,"reason":"Has QuickBooks experience.","missing":"Years of experience not stated"},
  alert_when="r.is_application === true && Number(r.match_score) >= 8", alert_subject="Strong applicant ({match_score}/10)", alert_body="{reason}\nFrom {from_address}"),
 dict(type="S", slug="task-due-date-reminders", category=C, name="Task due-date reminders to owners from a sheet",
  summary="Emails each task owner a reminder the day before and the day a task is due, until marked done.",
  tab="Tasks", cols=["task","owner_email","due_date","status","last_reminder"], when="daily 8",
  filter="String(r.status).toLowerCase() !== 'done' && daysUntil(r.due_date) !== null && daysUntil(r.due_date) <= 1 && daysUntil(r.due_date) >= -7 && (!has(r.last_reminder) || daysSince(r.last_reminder) >= 1)",
  mail=dict(to="{owner_email}", subject="Task due: {task}", body="'{task}' is due on {due_date}. Please mark it done in the sheet when finished."),
  mark=("last_reminder","new Date().toISOString().slice(0, 10)")),
 dict(type="S", slug="birthday-and-anniversary-greetings", category=C, name="Birthday and work anniversary greetings",
  summary="Sends a friendly birthday or anniversary email on the right day, from a simple team or client sheet.",
  tab="People", cols=["name","email","month_day","occasion","last_sent_year"], when="daily 8",
  filter="String(r.month_day) === new Date().toISOString().slice(5, 10) && String(r.last_sent_year) !== String(new Date().getFullYear())",
  mail=dict(to="{email}", subject="Happy {occasion}, {name}!", body="Hi {name},\n\nWishing you a wonderful {occasion} from all of us at {cfg.business_name}!\n\n{cfg.sender_name}"),
  mark=("last_sent_year","String(new Date().getFullYear())"),
  notes="Use the **month_day** column in the format MM-DD (for example 03-27)."),
 dict(type="S", slug="contract-expiry-reminder", category=C, name="Contract and certificate expiry reminder",
  summary="Emails you 30 days before a contract, licence or certificate expires.",
  tab="Contracts", cols=["item","party","expiry_date","reminded"], when="daily 8",
  filter="!has(r.reminded) && daysUntil(r.expiry_date) !== null && daysUntil(r.expiry_date) >= 0 && daysUntil(r.expiry_date) <= 30",
  mail=dict(to="{cfg.owner_email}", subject="Expiring: {item}", body="{item} with {party} expires on {expiry_date}. Renew or replace it."),
  mark=("reminded","new Date().toISOString().slice(0, 10)")),
 dict(type="I", slug="client-onboarding-intake-and-checklist", category=C, name="Client onboarding intake with welcome email and internal alert",
  summary="New client fills in an intake form. They get a welcome email with next steps and your team gets the details.",
  fields=["name","email","company","goals","start_date"], tab="Clients", trigger="form", form_title="Client onboarding",
  reply=dict(subject="Welcome, {name}! Next steps", body="Hi {name},\n\nThanks for the details. Here is what happens next:\n1. I review your goals ({goals}).\n2. We confirm the plan before {start_date}.\n3. You get a kickoff message.\n\n{cfg.sender_name}"),
  notify=dict(via="gmail", subject="New client: {company}", text="{name} ({email}) from {company}.\nGoals: {goals}\nStart: {start_date}")),
 dict(type="D", slug="weekly-project-status-update", category=C, name="Weekly project status update email from a tracker sheet",
  summary="Every Friday writes a short status update for stakeholders from your project tracker sheet.",
  tab="Projects", cols=["project","status","progress","next_step","blocker"], when="weekly 5 14",
  prompt="Write a short friendly weekly project status update for stakeholders from these rows: what is on track, what is at risk, blockers, and next steps. Max 150 words."),
 dict(type="I", slug="asset-checkout-tracker", category=C, name="Equipment checkout log with confirmation email",
  summary="Staff log equipment they borrow. Everything is recorded in a sheet and they get a confirmation with the return date.",
  fields=["name","email","item","return_date"], tab="Checkouts", trigger="form", form_title="Borrow equipment",
  reply=dict(subject="You borrowed: {item}", body="Hi {name},\n\nYou have borrowed {item}. Please return it by {return_date}.\n\n{cfg.business_name}")),
 dict(type="S", slug="equipment-return-overdue-reminder", category=C, name="Overdue equipment return reminder",
  summary="Emails people who have not returned borrowed equipment by the return date.",
  tab="Checkouts", cols=["name","email","item","return_date","returned","last_reminder"], when="daily 9",
  filter="!has(r.returned) && daysUntil(r.return_date) !== null && daysUntil(r.return_date) < 0 && (!has(r.last_reminder) || daysSince(r.last_reminder) >= 3)",
  mail=dict(to="{email}", subject="Please return {item}", body="Hi {name},\n\n{item} was due back on {return_date}. Please return it or reply if you need more time."),
  mark=("last_reminder","new Date().toISOString().slice(0, 10)")),
]
